BEGIN
INSERT INTO public.election_analysis_state(year,ballot,party,votes,share,seats,valid_votes,notes,data_release,direct_seats,list_seats)
SELECT 2026,'second',party,votes,round(votes::numeric/5375109*100,5),seats,5375109,'Amtliche Endfeststellung 27.03.2026; Landesebene.',
 'official-final-2026-state-20260327',direct_seats,list_seats FROM jsonb_to_recordset(verified_data) AS v(party text,votes bigint,seats integer,direct_seats integer,list_seats integer) WHERE true ON CONFLICT DO NOTHING;
-- Metadata only where existing numeric results already agree; manual discrepancies remain untouched.
UPDATE public.election_analysis_state s SET votes=coalesce(s.votes,v.votes),valid_votes=coalesce(s.valid_votes,5375109),seats=coalesce(s.seats,v.seats),share=coalesce(s.share,round(v.votes::numeric/5375109*100,5)),data_release='official-final-2026-state-20260327',direct_seats=v.direct_seats,list_seats=v.list_seats
FROM jsonb_to_recordset(verified_data) AS v(party text,votes bigint,seats integer,direct_seats integer,list_seats integer) WHERE s.year=2026 AND s.ballot='second' AND s.party=v.party AND (s.votes IS NULL OR s.votes=v.votes) AND(s.seats IS NULL OR s.seats=v.seats) AND(s.valid_votes IS NULL OR s.valid_votes=5375109)
AND(s.share IS NULL OR abs(s.share-round(v.votes::numeric/5375109*100,5))<=0.051)
AND(s.direct_seats IS NULL OR s.direct_seats=v.direct_seats) AND(s.list_seats IS NULL OR s.list_seats=v.list_seats);
